func TestGoldenOQ3(t *testing.T) {
	for _, g := range goldenRows {
		t.Run(g.schema+"/"+g.label, func(t *testing.T) {
			v, err := ParseOrdered([]byte(g.data))
			if err != nil {
				t.Fatalf("fixture parse: %v", err)
			}
			if err := Validate(v, g.schema, 1); err == nil {
				if g.expect != "" {
					t.Fatalf("expected error %q, got nil", g.expect)
				}
				return
			} else {
				var se *SchemaError
				if !errors.As(err, &se) {
					t.Fatalf("expected *SchemaError, got %T %q", err, err)
				}
				if se.Msg != g.expect {
					t.Errorf("error text mismatch:\n got %q\nwant %q", se.Msg, g.expect)
				}
			}
			if g.expect3 != "" {
				err3 := Validate(v, g.schema, 3)
				var se3 *SchemaError
				if !errors.As(err3, &se3) {
					t.Fatalf("max_errors=3: expected *SchemaError, got %v", err3)
				}
				if se3.Msg != g.expect3 {
					t.Errorf("max_errors=3 text mismatch:\n got %q\nwant %q", se3.Msg, g.expect3)
				}
			}
		})
	}
}
